 @Test void sameUuidAcrossThreeDomainsStillIsolated()throws Exception{UUID id=a.employeeId();owner.update("insert into public.customer_subject(id,tenant_id,status) values(?,?,'ACTIVE')",id,a.tenantId());owner.update("insert into public.customer_wechat_binding(id,tenant_id,customer_id,app_id,open_id,status) values(?,?,?,?,?,'ACTIVE')",UUID.randomUUID(),a.tenantId(),id,APP,"default-open");
  owner.update("insert into pet_control.platform_account(id,login_name,display_name,password_hash,status) values(?,?,?,?, 'ACTIVE')",id,"cx-platform","三域技术管理员",passwords.hash(staffPassword.toCharArray()));for(String permission:com.pet.platform.identity.application.authentication.PlatformPermissions.DECLARED)owner.update("insert into pet_control.platform_permission(account_id,permission_code) values(?,?)",id,permission);
  try{String ct=token();var sr=req("POST","/api/admin/auth/token/login",json.writeValueAsString(Map.of("tenantCode","cx-a","loginName","admin","password",staffPassword)));String st=data(sr).path("token").path("value").asText();var pre=req("GET","/api/platform/auth/csrf",null);String pc=pre.headers().allValues("Set-Cookie").stream().filter(v->v.startsWith("pet_dev_platform_pre=")).findFirst().orElseThrow().split(";",2)[0];var pl=req("POST","/api/platform/auth/login",json.writeValueAsString(Map.of("loginName","cx-platform","password",staffPassword)),"Cookie",pc,"X-CSRF-Token",data(pre).path("csrfToken").asText(),"Origin","http://localhost");assertEquals(200,pl.statusCode());String platformCookie=pl.headers().allValues("Set-Cookie").stream().filter(v->v.startsWith("pet_dev_platform_sid=")).findFirst().orElseThrow().split(";",2)[0];assertEquals(id.toString(),data(me(ct)).path("principalId").asText());assertEquals(id.toString(),data(req("GET","/api/admin/auth/me",null,"X-Staff-Token","Bearer "+st)).path("principalId").asText());assertEquals(id.toString(),data(req("GET","/api/platform/auth/me",null,"Cookie",platformCookie)).path("principalId").asText());
   req("POST","/api/customer/auth/logout-all",null,"X-Customer-Token","Bearer "+ct);assertEquals(200,req("GET","/api/admin/auth/me",null,"X-Staff-Token","Bearer "+st).statusCode());assertEquals(id.toString(),data(req("GET","/api/platform/auth/me",null,"Cookie",platformCookie)).path("principalId").asText());
  }finally{owner.update("delete from pet_control.platform_security_event where actor_id=? or target_id=?",id,id);owner.update("delete from pet_control.platform_session_cleanup where account_id=?",id);owner.update("delete from pet_control.platform_permission where account_id=?",id);owner.update("delete from pet_control.platform_account where id=?",id);}}
 @Test void currentLogoutInvalidatesOnlyCurrentCustomerDevice()throws Exception{String a=token(),b=token();assertEquals(200,req("POST","/api/customer/auth/logout",null,"X-Customer-Token","Bearer "+a).statusCode());error(me(a),401,"SESSION_EXPIRED");assertEquals(200,me(b).statusCode());}
