 @TestConfiguration(proxyBeanMethods=false) static class Probes {
  @Bean @Primary WechatMiniProgramGateway testWechatGateway(){return (config,code)->{CALLS.incrementAndGet();Object result=RESPONSES.get(code);if(result instanceof ErrorCode error)throw new BusinessException(error);return result instanceof WechatMiniProgramGateway.Identity i?i:new WechatMiniProgramGateway.Identity(config.appId(),"default-open",null);};}
  @Bean static BeanPostProcessor sessionFailureOnlyInTests(){return new BeanPostProcessor(){public Object postProcessAfterInitialization(Object bean,String name){if(!(bean instanceof CustomerSessionPort))return bean;return java.lang.reflect.Proxy.newProxyInstance(CustomerSessionPort.class.getClassLoader(),new Class[]{CustomerSessionPort.class},(proxy,method,args)->{if((method.getName().equals("create")&&sessionFailure)||(method.getName().equals("revokeBefore")&&cleanupFailure))throw new BusinessException(ErrorCode.DEPENDENCY_UNAVAILABLE);try{return method.invoke(bean,args);}catch(java.lang.reflect.InvocationTargetException e){throw e.getCause();}});}};}
  @Bean Probe customerProbe(CurrentPrincipalProvider provider,TenantTaskExecutor tasks){return new Probe(provider,tasks);}
 }
 @RestController static class Probe {
  private final CurrentPrincipalProvider provider;private final TenantTaskExecutor tasks;Probe(CurrentPrincipalProvider p,TenantTaskExecutor t){provider=p;tasks=t;}
  @GetMapping("/api/customer/__customer-test/principal") ApiResponse.Success<Map<String,String>> principal(){var p=provider.currentPrincipal().orElseThrow();return ApiResponse.success(Map.of("domain",p.principalType().name(),"id",p.principalId().toString(),"scope",p.grants().get(CustomerHttpAuthentication.SESSION_PERMISSION).types().iterator().next().name()));}
  @GetMapping("/api/customer/__customer-test/task") ApiResponse.Success<Void> task(){try(var s=TenantExecutionScope.forPermission(CustomerHttpAuthentication.SESSION_PERMISSION)){tasks.submit(()->null);return ApiResponse.success(null);}}
 }
